-- TSW planet-destroy probe: galactic story script of the campaign "TSWP PROBE" (generated by
-- tools/probe_mod/tsw_planet_destroy/build_mod.py from tswp_story.lua). docs/re/TSW_PLANET_DESTROY.md sec. 8: owner and
-- starbase of @@TARGET@@ after a TSW battle. Every 2 s it builds a status line (destroyed flag, owner faction, starbase
-- objects at the planet with their owner, Death Star alive, Rebel / Empire objects at the planet) and keeps it as a
-- heap record "TSWP1|GALAXY|<seq>|...|END" (TSWP_Records; tswp_reader.py scans for it) whenever it changed. The plot's XML event TSWP_Heard (STORY_PLANET_DESTROYED
-- @@TARGET@@) has a SCREEN_TEXT reward only: the spec expects it NEVER fires after a tactical TSW kill (sec. 7).
require("PGStoryMode")

TSWP_TARGET = "@@TARGET@@"
TSWP_BASES = { "Rebel_Star_Base_1", "Rebel_Star_Base_2", "Rebel_Star_Base_3", "Rebel_Star_Base_4", "Rebel_Star_Base_5",
	"Empire_Star_Base_1", "Empire_Star_Base_2", "Empire_Star_Base_3", "Empire_Star_Base_4", "Empire_Star_Base_5" }

if TSWP_Records == nil then
	TSWP_Records = {}
	TSWP_Seq = 0
end

function TSWP_Say(kind, s)
	TSWP_Seq = TSWP_Seq + 1
	TSWP_Records[TSWP_Seq] = "TSWP1|" .. kind .. "|" .. TSWP_Seq .. "|" .. s .. "|END"
end

function Definitions()
	TSWP_Say("STORYDEF", "galactic story Definitions ran")
	StoryModeEvents = { TSWP_Begin = TSWP_State_Begin, TSWP_Heard = TSWP_State_Heard }
	TSWP_Started = false
	TSWP_Last = ""
end

function TSWP_Str(f)
	local ok, v = pcall(f)
	if ok and v ~= nil then
		return tostring(v)
	end
	return "?"
end

function TSWP_State_Begin(message)
	if message == OnEnter and not TSWP_Started then
		TSWP_Started = true
		TSWP_Say("STORYBEGIN", "TSWP_Begin entered")
		Create_Thread("TSWP_Watch")
	end
end

function TSWP_State_Heard(message)
	if message == OnEnter then
		TSWP_Say("HEARD", "GALACTIC PLOT HEARD PLANET_DESTROYED " .. TSWP_TARGET .. " t=" .. TSWP_Str(GetCurrentTime) ..
			" (spec: never)")
	end
end

function TSWP_Status()
	local planet = FindPlanet(TSWP_TARGET)
	if not TestValid(planet) then
		return "planet " .. TSWP_TARGET .. " not found"
	end
	local s = "destroyed=" .. TSWP_Str(function() return planet.Is_Planet_Destroyed() end) ..
		" owner=" .. TSWP_Str(function() return planet.Get_Owner().Get_Faction_Name() end) .. " starbase="
	local n = 0
	for _, t in ipairs(TSWP_BASES) do
		local ok, list = pcall(Find_All_Objects_Of_Type, t)
		if ok and type(list) == "table" then
			for _, obj in pairs(list) do
				local okp, here = pcall(function() return obj.Get_Planet_Location() == planet end)
				if okp and here then
					s = s .. t .. "(" .. TSWP_Str(function() return obj.Get_Owner().Get_Faction_Name() end) .. ") "
					n = n + 1
				end
			end
		end
	end
	if n == 0 then
		s = s .. "none "
	end
	-- the by-type search above found no station at the start of the 2026-10-31 run; the planet's own level is direct
	s = s .. "sb_level=" .. TSWP_Str(function() return planet.Get_Starbase_Level() end) .. " "
	local ds = nil
	pcall(function() ds = Find_First_Object("Death_Star_II") end)
	s = s .. "death_star=" .. TSWP_Str(function() return TestValid(ds) end)
	s = s .. " ds_at=" .. TSWP_Str(function() return ds.Get_Planet_Location().Get_Type().Get_Name() end)
	for _, fac in ipairs({ "Rebel", "Empire" }) do
		local c = 0
		local types = {}
		local names = ""
		local p = Find_Player(fac)
		local ok, list = pcall(Find_All_Objects_Of_Type, p)
		if ok and type(list) == "table" then
			for _, obj in pairs(list) do
				local okp, here = pcall(function() return obj.Get_Planet_Location() == planet end)
				if okp and here then
					c = c + 1
					local okn, tn = pcall(function() return obj.Get_Type().Get_Name() end)
					if okn and tn and not types[tn] then
						types[tn] = true
						names = names .. tn .. ","
					end
				end
			end
		end
		-- a1mem.scan returns 400 bytes per hit: keep the whole record under that
		s = s .. " " .. fac .. "_objects_here=" .. c .. "[" .. string.sub(names, 1, 80) .. "]"
	end
	return s
end

function TSWP_Watch()
	pcall(Game_Message, "TEXT_TSWP_STORY_LUA")
	while true do
		local ok, s = pcall(TSWP_Status)
		if not ok then
			s = "status error " .. tostring(s)
		end
		if s ~= TSWP_Last then
			TSWP_Last = s
			TSWP_Say("GALAXY", "t=" .. TSWP_Str(GetCurrentTime) .. " " .. s)
		end
		Sleep(2)
	end
end
